// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.animation.core.LinearEasingimport androidx.compose.animation.core.RepeatModeimport androidx.compose.animation.core.animateFloatimport androidx.compose.animation.core.infiniteRepeatableimport androidx.compose.animation.core.rememberInfiniteTransitionimport androidx.compose.animation.core.tweenimport androidx.compose.foundation.Canvasimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableFloatStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.geometry.Offsetimport androidx.compose.ui.geometry.Sizeimport androidx.compose.ui.graphics.Brushimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.drawscope.Strokeimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.theme.AccentAuroraEndimport com.roshan.persona.ui.theme.AccentAuroraStartimport com.roshan.persona.ui.theme.AccentSuccessimport com.roshan.persona.ui.theme.AccentWarnimport kotlinx.coroutines.delay/** * Splash screen — branded cold start with rotating aurora ring. * * Wired to: *   - CrashRecoveryManager.shouldBootInSafeMode() (passed in as parameter) *   - AppInitializers progress (passed in as parameter) *   - IntegrityAttestation state (passed in as parameter) * * After [onFinished] is invoked (typically after 1.5s or when init completes), * the host navigates to Home or App Lock. */@Composablefun SplashScreen(    initProgress: Float,             // 0f..1f — from AppInitializers    initStepDescription: String,     // e.g. "Loading brain layers..."    safeMode: Boolean,               // from CrashRecoveryManager    integrityVerified: Boolean?,     // null=not checked, true=verified, false=compromised    appVersion: String,              // from BuildConfig    buildNumber: String,             // from BuildConfig    onFinished: () -> Unit,) {    // Auto-finish after progress reaches 100% + small grace period.    LaunchedEffect(initProgress) {        if (initProgress >= 1f) {            delay(300)            onFinished()        }    }    val infinite = rememberInfiniteTransition(label = "splash_aurora")    val rotation by infinite.animateFloat(        initialValue = 0f,        targetValue = 360f,        animationSpec = infiniteRepeatable(            animation = tween(8000, easing = LinearEasing),            repeatMode = RepeatMode.Restart,        ),        label = "rotation",    )    Box(        modifier = Modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background),        contentAlignment = Alignment.Center,    ) {        Column(            horizontalAlignment = Alignment.CenterHorizontally,            verticalArrangement = Arrangement.Center,        ) {            // Aurora ring (animated)            Box(                modifier = Modifier.size(160.dp),                contentAlignment = Alignment.Center,            ) {                Canvas(modifier = Modifier.fillMaxSize()) {                    val canvasSize = size.minDimension                    val stroke = canvasSize * 0.04f                    val radius = (canvasSize - stroke) / 2f                    val center = Offset(canvasSize / 2f, canvasSize / 2f)                    drawArc(                        brush = Brush.sweepGradient(                            colors = listOf(                                AccentAuroraStart,                                AccentAuroraEnd,                                AccentAuroraStart,                            ),                        ),                        startAngle = rotation,                        sweepAngle = 270f,                        useCenter = false,                        topLeft = Offset(center.x - radius, center.y - radius),                        size = Size(radius * 2, radius * 2),                        style = Stroke(width = stroke),                    )                }                // Center "N" monogram                Text(                    text = "N",                    style = MaterialTheme.typography.displayLarge,                    fontWeight = FontWeight.Bold,                    color = MaterialTheme.colorScheme.onBackground,                )            }            Spacer(modifier = Modifier.size(24.dp))            Text(                text = "NOUS",                style = MaterialTheme.typography.displayLarge,                fontWeight = FontWeight.Bold,                color = MaterialTheme.colorScheme.onBackground,            )            Spacer(modifier = Modifier.size(8.dp))            Text(                text = "Your Autonomous Mind",                style = MaterialTheme.typography.bodyLarge,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )            Spacer(modifier = Modifier.size(48.dp))            // Init progress bar            androidx.compose.material3.LinearProgressIndicator(                progress = { initProgress },                modifier = Modifier                    .padding(horizontal = 64.dp),                color = AccentAuroraStart,                trackColor = MaterialTheme.colorScheme.surfaceVariant,            )            Spacer(modifier = Modifier.size(12.dp))            Text(                text = initStepDescription,                style = MaterialTheme.typography.labelMedium,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )            Spacer(modifier = Modifier.size(48.dp))            // Integrity badge            when (integrityVerified) {                true -> Text(                    text = "✓ Device verified",                    style = MaterialTheme.typography.labelMedium,                    color = AccentSuccess,                )                false -> Text(                    text = "⚠ Device compromised — sensitive features disabled",                    style = MaterialTheme.typography.labelMedium,                    color = AccentWarn,                )                null -> Text(                    text = "Verifying device integrity...",                    style = MaterialTheme.typography.labelMedium,                    color = MaterialTheme.colorScheme.onSurfaceVariant,                )            }            // Safe mode badge            if (safeMode) {                Spacer(modifier = Modifier.size(8.dp))                Text(                    text = "⚠ Safe Mode (3+ crashes detected)",                    style = MaterialTheme.typography.labelMedium,                    color = AccentWarn,                )            }            Spacer(modifier = Modifier.size(48.dp))            Text(                text = "v$appVersion · build #$buildNumber",                style = MaterialTheme.typography.labelSmall,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )        }    }}